import { test, expect } from '@playwright/test';

test.describe('Error Messages Screen Reader Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('about:blank');
    await page.setContent(`
      <form id="testForm">
        <div>
          <label for="email">Email Address</label>
          <input 
            id="email" 
            type="email" 
            aria-describedby="emailError"
            aria-invalid="false"
          />
          <div id="emailError" role="alert" aria-live="polite" style="display:none; color: red;">
            Please enter a valid email address
          </div>
        </div>
        <div>
          <label for="password">Password</label>
          <input 
            id="password" 
            type="password"
            aria-describedby="passwordError"
            aria-invalid="false"
          />
          <div id="passwordError" role="alert" aria-live="assertive" style="display:none; color: red;">
            Password must be at least 8 characters long
          </div>
        </div>
        <button type="submit">Submit</button>
      </form>
    `);
  });

  test('should have proper ARIA attributes on error messages', async ({ page }) => {
    const emailError = page.locator('#emailError');
    const passwordError = page.locator('#passwordError');

    // Verify error messages have role="alert"
    await expect(emailError).toHaveAttribute('role', 'alert');
    await expect(passwordError).toHaveAttribute('role', 'alert');

    // Verify error messages have aria-live attribute for screen reader announcements
    await expect(emailError).toHaveAttribute('aria-live', 'polite');
    await expect(passwordError).toHaveAttribute('aria-live', 'assertive');
  });

  test('should associate error messages with form inputs using aria-describedby', async ({ page }) => {
    const emailInput = page.locator('#email');
    const passwordInput = page.locator('#password');

    // Verify inputs reference their error messages
    await expect(emailInput).toHaveAttribute('aria-describedby', 'emailError');
    await expect(passwordInput).toHaveAttribute('aria-describedby', 'passwordError');
  });

  test('should update aria-invalid when error occurs', async ({ page }) => {
    const emailInput = page.locator('#email');
    const emailError = page.locator('#emailError');

    // Initially, aria-invalid should be false
    await expect(emailInput).toHaveAttribute('aria-invalid', 'false');

    // Simulate error state
    await emailInput.fill('invalid-email');
    await page.evaluate(() => {
      const input = document.getElementById('email');
      const error = document.getElementById('emailError');
      if (input && error) {
        input.setAttribute('aria-invalid', 'true');
        (error as HTMLElement).style.display = 'block';
      }
    });

    // Verify aria-invalid is updated
    await expect(emailInput).toHaveAttribute('aria-invalid', 'true');
    await expect(emailError).toBeVisible();
  });

  test('should make error messages visible and announced to screen readers', async ({ page }) => {
    const emailError = page.locator('#emailError');

    // Initially error should be hidden
    await expect(emailError).not.toBeVisible();

    // Trigger error display
    await page.evaluate(() => {
      const error = document.getElementById('emailError');
      if (error) {
        (error as HTMLElement).style.display = 'block';
      }
    });

    // Error should now be visible and accessible
    await expect(emailError).toBeVisible();
    await expect(emailError).toContainText('Please enter a valid email address');
  });

  test('should have descriptive error text for screen reader users', async ({ page }) => {
    const emailError = page.getByText('Please enter a valid email address');
    const passwordError = page.getByText('Password must be at least 8 characters long');

    // Verify error messages are present and contain helpful text
    await expect(emailError).toBeTruthy();
    await expect(passwordError).toBeTruthy();
  });

  test('should clear error state when input is corrected', async ({ page }) => {
    const emailInput = page.locator('#email');
    const emailError = page.locator('#emailError');

    // Set error state
    await page.evaluate(() => {
      const input = document.getElementById('email');
      const error = document.getElementById('emailError');
      if (input && error) {
        input.setAttribute('aria-invalid', 'true');
        (error as HTMLElement).style.display = 'block';
      }
    });

    await expect(emailInput).toHaveAttribute('aria-invalid', 'true');
    await expect(emailError).toBeVisible();

    // Clear error state
    await page.evaluate(() => {
      const input = document.getElementById('email');
      const error = document.getElementById('emailError');
      if (input && error) {
        input.setAttribute('aria-invalid', 'false');
        (error as HTMLElement).style.display = 'none';
      }
    });

    // Verify error is cleared
    await expect(emailInput).toHaveAttribute('aria-invalid', 'false');
    await expect(emailError).not.toBeVisible();
  });
});
